const body = $json.body || $json || {};
const clientId = String(body.client_id || '').trim();
const esUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId);

const cantidad = Math.min(Math.max(Number(body.cantidad) || 9, 1), 20);
const formato = ['post', 'story', 'cuadrado'].includes(body.formato) ? body.formato : 'post';

return [{
  json: {
    client_id: esUuid ? clientId : '',
    cantidad,
    formato,
    // Tema opcional para acotar el lote: "infantil", "cocina", "navidad"...
    tema: String(body.tema || '').trim(),
  },
}];

const pet = $('Leer petición').first().json;
const fila = $input.first().json;
const config = (fila && fila.config) || {};

const handle = String(config.ig_handle || '').trim();
const web = String(config.web || '').trim();

return [{
  json: {
    ...pet,
    tono: String(config.tono || '').trim() ||
      'cercano y natural, tratando de tú, sin lenguaje publicitario ni exageraciones',
    handle,
    // Pie de la pieza: lo que se ve en pequeño dentro de la imagen.
    pie: [handle, web].filter(Boolean).join(' · '),
    marca: {
      primario: String(config.color_primario || '').trim() || undefined,
      secundario: String(config.color_secundario || '').trim() || undefined,
    },
    // Producto estrella: la palabra que lo identifica en el nombre y cuánto
    // debe ocupar de cada lote. Sin configurar, el lote sale repartido entre
    // familias sin favorecer a ninguna.
    producto_estrella: String(config.producto_estrella || '').trim(),
    peso_estrella: Math.min(100, Math.max(0, Number(config.peso_estrella) || 60)),
    listo: Boolean(fila && fila.client_id),
  },
}];

