// Palabras que aparecen en medio catálogo y no distinguen un producto de otro.
const VACIAS = new Set([
  'con', 'para', 'por', 'del', 'las', 'los', 'una', 'uno', 'sin',
  'tejido', 'basic', 'combi', 'juego', 'liso', 'lisos', 'lisa', 'lisas',
  'hilos', 'digital', 'estampado', 'enrollable',
]);

const cfg = $('Leer configuración').first().json;
const filas = $input.all().map((i) => i.json).filter((p) => p && p.name);

// Sin foto no hay pieza que valga: se descartan antes de gastar tokens.
let candidatos = filas.filter((p) => p.image_url && p.available !== false);

if (cfg.tema) {
  const t = cfg.tema.toLowerCase();
  const filtrados = candidatos.filter((p) =>
    (p.name + ' ' + (p.category || '')).toLowerCase().includes(t)
  );
  // Si el tema no casa con nada, mejor un lote variado que un lote vacío.
  if (filtrados.length >= cfg.cantidad) candidatos = filtrados;
}

if (!candidatos.length) {
  return [{ json: { error: 'El catálogo no tiene productos con foto.', productos: [] } }];
}

// Barajado de Fisher-Yates. Hace falta porque el catálogo viene ordenado por
// fecha de alta y los productos contiguos suelen ser variaciones del mismo
// modelo: sin barajar salen nueve piezas casi idénticas.
const baraja = candidatos.slice();
for (let i = baraja.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [baraja[i], baraja[j]] = [baraja[j], baraja[i]];
}

const palabras = (nombre) =>
  String(nombre)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    // Fuera referencias (llevan cifras) y palabras que no distinguen nada.
    .filter((w) => w.length > 2 && !/\d/.test(w) && !VACIAS.has(w));

// Reparte una lista en grupos y va cogiendo uno de cada grupo por vuelta, de
// modo que salgan cosas distintas aunque un grupo tenga cientos de productos.
const repartir = (lista, cuantos, clavePara) => {
  const grupos = new Map();
  for (const p of lista) {
    const k = clavePara(p);
    if (!grupos.has(k)) grupos.set(k, []);
    grupos.get(k).push(p);
  }
  const orden = [...grupos.values()].sort((a, b) => b.length - a.length);
  const salida = [];
  for (let vuelta = 0; salida.length < cuantos && vuelta < 200; vuelta++) {
    let hubo = false;
    for (const g of orden) {
      if (salida.length >= cuantos) break;
      if (g[vuelta]) { salida.push(g[vuelta]); hubo = true; }
    }
    if (!hubo) break;
  }
  return salida;
};

// === Qué distingue a un producto de sus hermanos ===
// Dentro de una familia enorme ("estor enrollable estampado digital ...") lo
// que cambia es el tema: zen, paisajes, infantil, ciudades. Se localiza sola,
// sin listas escritas a mano: es la palabra menos frecuente del nombre que aun
// así se repite lo bastante como para ser un tema y no ruido.
const temaDe = (lista) => {
  const frec = new Map();
  const cache = new Map();
  for (const p of lista) {
    const ws = [...new Set(palabras(p.name))];
    cache.set(p, ws);
    for (const w of ws) frec.set(w, (frec.get(w) || 0) + 1);
  }
  return (p) => {
    let mejor = '';
    let mejorFrec = Infinity;
    for (const w of cache.get(p) || []) {
      const f = frec.get(w);
      // El mínimo de 3 evita quedarse con una errata o una palabra suelta.
      if (f >= 3 && f < mejorFrec) { mejorFrec = f; mejor = w; }
    }
    return mejor || 'otros';
  };
};

// === Reparto ===
// Decide el código, no la IA. Cuando se le pasaba una muestra y se le pedía
// "elige los más variados", esquivaba la familia dominante justamente por ser
// la más repetida: con un catálogo 84% estores salían lotes con 2 estores y 7
// de ropa de cama, o sea publicando lo que menos se vende.
//
// Cuánto pesa el producto estrella lo decide el cliente en el panel, no una
// constante escondida aquí: quien sabe qué le conviene vender es él.
const estrella = String(cfg.producto_estrella || '').toLowerCase().trim();
const principales = estrella
  ? baraja.filter((p) => p.name.toLowerCase().includes(estrella))
  : [];
const resto = estrella
  ? baraja.filter((p) => !p.name.toLowerCase().includes(estrella))
  : baraja;

let cuotaPrincipal = principales.length
  ? Math.round((cfg.cantidad * cfg.peso_estrella) / 100)
  : 0;
cuotaPrincipal = Math.min(cuotaPrincipal, principales.length);

// Sin producto estrella configurado se agrupa por las dos primeras palabras,
// que es una familia razonable en cualquier catálogo.
const porFamilia = (p) => palabras(p.name).slice(0, 2).join(' ') || 'otros';

const elegidos = [
  // Dentro de los estores, variedad de temas; entre el resto, variedad de familia.
  ...repartir(principales, cuotaPrincipal, temaDe(principales)),
  ...repartir(resto, cfg.cantidad - cuotaPrincipal, porFamilia),
];

// Si una parte no llegó a llenar su cuota (catálogo corto), la otra completa.
if (elegidos.length < cfg.cantidad) {
  const yaEstan = new Set(elegidos.map((p) => p.id));
  for (const p of baraja) {
    if (elegidos.length >= cfg.cantidad) break;
    if (!yaEstan.has(p.id)) elegidos.push(p);
  }
}

return [{
  json: {
    ...cfg,
    total_catalogo: candidatos.length,
    de_producto_estrella: elegidos.filter(
      (p) => estrella && p.name.toLowerCase().includes(estrella)
    ).length,
    productos: elegidos.map((p, i) => ({
      indice: i,
      id: p.id,
      nombre: p.name,
      precio: p.price,
      moneda: p.currency || 'EUR',
      image_url: p.image_url,
      url: p.url,
    })),
  },
}];

const cfg = $('Muestrear productos').first().json;
const productos = cfg.productos || [];

let datos = {};
try {
  const bruto = $input.first().json;
  const contenido = bruto.choices && bruto.choices[0] && bruto.choices[0].message
    ? bruto.choices[0].message.content
    : '{}';
  datos = JSON.parse(contenido);
} catch (e) {
  datos = {};
}

const piezas = Array.isArray(datos.piezas) ? datos.piezas : [];

// Tope de caracteres del titular. La plantilla parte en dos líneas de unos 28
// caracteres; más allá de 46 empieza a comerse palabras con puntos suspensivos.
const MAX_TITULAR = 46;

const salida = [];
const usados = new Set();
const descartadas = [];

// Comparación laxa de nombres: minúsculas y sin espacios de más. No se
// normalizan acentos porque el nombre debe venir copiado tal cual.
const clave = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const porNombre = new Map(productos.map((p) => [clave(p.nombre), p]));

for (const p of piezas) {
  let producto = productos[Number(p.indice)];

  // El modelo debe devolver el nombre exacto del producto, y aquí se comprueba
  // que cuadre con el índice. Sin esta verificación se cuela lo peor que puede
  // pasar en esta fase: un texto que habla de un producto distinto del que sale
  // en la foto (una vez escribió sobre sábanas de algodón sobre la foto de un
  // estor). El nombre manda; si tampoco casa, la pieza se tira.
  const dicho = clave(p.nombre);
  if (dicho && (!producto || clave(producto.nombre) !== dicho)) {
    const porTexto = porNombre.get(dicho);
    if (porTexto) {
      producto = porTexto;
    } else {
      descartadas.push({ titular: p.titular, nombre_dicho: p.nombre });
      continue;
    }
  }

  if (!producto) {
    descartadas.push({ titular: p.titular, motivo: 'índice inexistente' });
    continue;
  }

  const i = productos.indexOf(producto);
  if (usados.has(i)) continue;
  usados.add(i);

  let titular = String(p.titular || '').trim().replace(/\s+/g, ' ');
  if (!titular) titular = producto.nombre;
  if (titular.length > MAX_TITULAR) {
    titular = titular.slice(0, MAX_TITULAR).replace(/[\s,;:.]+\S*$/, '');
  }

  // El modelo tiende a meter los hashtags dentro de la caption aunque se le
  // pida un campo aparte. En vez de fiarnos, se recogen de los dos sitios y se
  // limpian de la caption: así la etiqueta siempre acaba en su columna y el
  // texto no las lleva duplicadas.
  let caption = String(p.caption || '').trim();
  const enTexto = (caption.match(/#[\p{L}\p{N}_]+/gu) || []).map((h) => h.slice(1));
  caption = caption.replace(/#[\p{L}\p{N}_]+/gu, '').replace(/[ \t]{2,}/g, ' ').trim();

  const hashtags = [
    ...(Array.isArray(p.hashtags) ? p.hashtags : []).map((h) => String(h)),
    ...enTexto,
  ]
    .map((h) => h.replace(/^#/, '').trim())
    .filter(Boolean)
    .filter((h, i, a) => a.findIndex((x) => x.toLowerCase() === h.toLowerCase()) === i)
    .slice(0, 12);

  // Etiqueta con el tipo de producto. La escribe la IA, pero se comprueba que
  // comparta alguna palabra con el nombre real: sin eso podría poner "Cojín"
  // sobre la foto de un estor, que es peor que no poner nada. Si no cuadra, se
  // recurre a las dos primeras palabras con significado del propio nombre.
  const significativas = (s) =>
    String(s || '')
      .toLowerCase()
      .replace(/[^\p{L}\p{N}\s]/gu, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 3 && !/\d/.test(w));

  const palabrasNombre = new Set(significativas(producto.nombre));
  const tipoDicho = String(p.tipo || '').trim().slice(0, 28);
  const cuadra =
    tipoDicho && significativas(tipoDicho).some((w) => palabrasNombre.has(w));

  const etiqueta = cuadra
    ? tipoDicho
    : (() => {
        const ws = significativas(producto.nombre).slice(0, 2);
        if (!ws.length) return '';
        const t = ws.join(' ');
        return t.charAt(0).toUpperCase() + t.slice(1);
      })();

  salida.push({
    json: {
      client_id: cfg.client_id,
      formato: cfg.formato,
      titular,
      caption,
      etiqueta,
      hashtags,
      pie: cfg.pie,
      marca: cfg.marca,
      producto: {
        id: producto.id,
        image_url: producto.image_url,
        price: producto.precio,
        currency: producto.moneda,
        url: producto.url,
        nombre: producto.nombre,
      },
    },
  });
}

// El prompt prohíbe estas muletillas, pero un prompt no es una garantía. No se
// descarta la pieza por caer en una —sería tirar trabajo bueno por una frase—:
// se marca para que salte a la vista de quien aprueba.
const MULETILLAS = [
  'ideal para', 'perfecto para', 'perfecta para', 'un toque especial',
  'transforma tu hogar', 'el complemento perfecto', 'sinónimo de',
  'no puede faltar', 'dale vida a', 'la calidad que mereces',
  '¿a qué esperas', 'no te lo pierdas',
];

// Materiales que el modelo se ha visto inventar: etiquetó #algodón unas sábanas
// que en su nombre solo dicen "satén". Es la clase de detalle que nadie revisa
// y que en una ficha de producto sería publicidad engañosa.
const MATERIALES = [
  'algodón', 'algodon', 'lino', 'seda', 'satén', 'saten', 'franela',
  'microfibra', 'poliéster', 'poliester', 'terciopelo', 'lana', 'bambú',
  'percal', 'plumón', 'plumon',
];

// Trozos de los ejemplos del prompt. El modelo copió uno palabra por palabra
// («Hay ventanas que dan a un patio de luces...») y se habría publicado tal
// cual: un ejemplo didáctico mío firmado por la tienda. Un ejemplo enseña el
// tono, pero también es texto listo para copiar.
const EJEMPLOS = [
  'patio de luces',
  'una playa al atardecer',
  'no cansa a los dos meses',
  'ya no te planteas cambiarlo',
  'se gana el sueldo',
  'todo el argumento',
];

// Rotación de estilos visuales. Con una sola plantilla, nueve piezas seguidas
// en la cuadrícula del perfil cantan a bot: misma banda, misma composición,
// cambiando solo la foto. "sangre" pesa el doble porque es el que menos parece
// una ficha de producto.
const ROTACION = ['sangre', 'banda', 'sangre', 'marco'];

const arranques = new Map();

for (const item of salida) {
  const texto = (item.json.caption + ' ' + item.json.titular).toLowerCase();
  const avisos = MULETILLAS.filter((m) => texto.includes(m));

  // Por palabra entera, no por subcadena: buscando "lana" con includes() saltaba
  // dentro de "plana" y avisaba de un material que nadie había mencionado. Un
  // aviso falso es peor que ninguno, porque enseña a ignorarlos.
  const nombreProd = item.json.producto.nombre.toLowerCase();
  const conHashtags = texto + ' ' + item.json.hashtags.join(' ').toLowerCase();
  const mencion = (t, m) =>
    new RegExp('(^|[^\\p{L}])' + m + '($|[^\\p{L}])', 'iu').test(t);

  for (const m of MATERIALES) {
    if (mencion(conHashtags, m) && !mencion(nombreProd, m)) {
      avisos.push('menciona «' + m + '» y no está en el nombre del producto');
    }
  }

  if (item.json.hashtags.length < 6) {
    avisos.push('solo ' + item.json.hashtags.length + ' hashtags');
  }

  for (const e of EJEMPLOS) {
    if (texto.includes(e)) avisos.push('copia un ejemplo del prompt');
  }

  // "Este estor...", "Esta funda..." en cualquier punto, no solo al principio:
  // al prohibirlo solo en el arranque, la muletilla se mudó a la segunda frase
  // y las nueve piezas del lote volvían a sonar igual.
  const primeraDelTipo = (item.json.etiqueta || '').split(/\s+/)[0];
  if (primeraDelTipo) {
    const re = new RegExp('\\b(este|esta)\\s+' + primeraDelTipo, 'i');
    if (re.test(item.json.caption)) avisos.push('«este/esta» + producto');
  }

  // Dos piezas del mismo lote que arrancan igual cantan muchísimo en el perfil.
  const arranque = item.json.caption.toLowerCase().split(/\s+/).slice(0, 3).join(' ');
  if (arranques.has(arranque)) avisos.push('arranque repetido');
  arranques.set(arranque, true);

  item.json.avisos = avisos;
  item.json.estilo = ROTACION[salida.indexOf(item) % ROTACION.length];
}

if (descartadas.length) {
  console.log('Piezas descartadas por no cuadrar con su producto:', JSON.stringify(descartadas));
}

if (!salida.length) {
  return [{ json: { vacio: true, motivo: 'La IA no devolvió ninguna pieza utilizable.' } }];
}

return salida;

const copy = $('Parsear copys').item.json;
const render = $json || {};

// El render devuelve la URL pública; el copy viene del paso anterior. Aquí se
// vuelven a juntar para escribir una fila completa en content_items.
const caption = [copy.caption, (copy.hashtags || []).map((h) => '#' + h).join(' ')]
  .filter(Boolean)
  .join('\n\n');

return {
  json: {
    client_id: copy.client_id,
    formato: copy.formato,
    titular: copy.titular,
    caption,
    hashtags: copy.hashtags || [],
    media_url: render.url || '',
    producto_id: copy.producto.id,
    producto_nombre: copy.producto.nombre,
    avisos: copy.avisos || [],
    estilo: copy.estilo || '',
    etiqueta: copy.etiqueta || '',
    ok_render: Boolean(render.url),
  },
};

const items = $input.all().map((i) => i.json);

return [{
  json: {
    ok: true,
    piezas_creadas: items.length,
    mensaje: items.length
      ? 'Listas ' + items.length + ' piezas. Revísalas y apruébalas en el panel.'
      : 'No se generó ninguna pieza.',
  },
}];
